  --space-xl: 32px;

  /* Efectos */
  --glow-cyan:   0 0 8px rgba(0, 212, 255, 0.6),  0 0 20px rgba(0, 212, 255, 0.3);
  --glow-green:  0 0 8px rgba(0, 255, 136, 0.6),  0 0 20px rgba(0, 255, 136, 0.3);
  --glow-yellow: 0 0 8px rgba(255, 215, 0, 0.7),  0 0 24px rgba(255, 215, 0, 0.4);
  --glow-red:    0 0 8px rgba(255, 51, 102, 0.7),  0 0 20px rgba(255, 51, 102, 0.4);

  /* Transiciones */
  --transition-fast:   150ms ease;
  --transition-normal: 300ms ease;
  --transition-slow:   600ms ease;

  /* Layout */
  --header-height: 70px;
  --footer-height: 40px;
  --panel-radius:  6px;
}

/* ============================================================
   2. RESET Y BASE GLOBAL
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

body {
  background-color: var(--color-bg-deep);
  color: var(--color-cyan);
  font-family: var(--font-mono);
  font-size: var(--font-size-base);
  line-height: 1.4;
  -webkit-font-smoothing: antialiased;
}

/* ============================================================
   3. APP ROOT — CONTENEDOR PRINCIPAL
   ============================================================ */
#app-root {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
}

/* ============================================================
   4. CANVAS LAYER — PARTÍCULAS DE FONDO
   ============================================================ */
#canvas-container {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

#canvas-particles,
#canvas-connections {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

/* ============================================================
   5. HEADER
   ============================================================ */
#dashboard-header {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
  padding: 0 var(--space-lg);
  background-color: var(--color-bg-panel);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

#header-left {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

#system-status-indicator {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-green);
  box-shadow: var(--glow-green);
  animation: pulse-dot 2s ease-in-out infinite;
}

#dashboard-title {
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-cyan);
  text-shadow: var(--glow-cyan);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.header-subtitle {
  font-size: var(--font-size-xs);
  color: var(--color-cyan);
  opacity: 0.55;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-top: 2px;
}

#header-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
}

#header-right {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

#live-clock {
  font-size: var(--font-size-lg);
  color: var(--color-cyan);
  text-shadow: var(--glow-cyan);
  letter-spacing: 0.1em;
  font-weight: 700;
}

/* ============================================================
   6. KPI BAR
   ============================================================ */
#kpi-bar {
  position: relative;
  z-index: 10;
  display: flex;
  align-items: stretch;
  gap: 1px;
  height: 64px;
  background-color: var(--color-border);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.kpi-card {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  background-color: var(--color-bg-panel);
  padding: var(--space-xs) var(--space-sm);
  cursor: default;
  transition: background-color var(--transition-fast);
  position: relative;
  overflow: hidden;
}

.kpi-card::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--color-cyan);
  opacity: 0;
  transition: opacity var(--transition-fast);
}

.kpi-card:hover {
  background-color: var(--color-bg-panel-hover);
}

.kpi-card:hover::before {
  opacity: 1;
}

.kpi-label {
  font-size: var(--font-size-xs);
  color: var(--color-cyan);
  opacity: 0.6;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.kpi-value {
  font-size: var(--font-size-lg);
  font-weight: 700;
  color: var(--color-cyan);
  text-shadow: var(--glow-cyan);
  line-height: 1;
}

.kpi-unit {
  font-size: var(--font-size-xs);
  color: var(--color-cyan);
  opacity: 0.5;
  letter-spacing: 0.06em;
}

/* KPI IDs — colores de acento individuales */
#kpi-deployment-freq .kpi-value { color: var(--color-green); text-shadow: var(--glow-green); }
#kpi-deployment-freq::before    { background-color: var(--color-green); }

#kpi-lead-time .kpi-value       { color: var(--color-cyan); text-shadow: var(--glow-cyan); }

#kpi-mttr .kpi-value            { color: var(--color-yellow); text-shadow: var(--glow-yellow); }
#kpi-mttr::before               { background-color: var(--color-yellow); }

#kpi-change-fail .kpi-value     { color: var(--color-red); text-shadow: var(--glow-red); }
#kpi-change-fail::before        { background-color: var(--color-red); }

#kpi-open-incidents .kpi-value  { color: var(--color-yellow); text-shadow: var(--glow-yellow); }
#kpi-open-incidents::before     { background-color: var(--color-yellow); }

#kpi-pipeline-health .kpi-value { color: var(--color-green); text-shadow: var(--glow-green); }
#kpi-pipeline-health::before    { background-color: var(--color-green); }

/* ============================================================
   7. DASHBOARD MAIN — GRID DE PANELES
   ============================================================ */
#dashboard-main {
  position: relative;
  z-index: 10;
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 1px;
  background-color: var(--color-border);
  overflow: hidden;
  min-height: 0;
}

/* ============================================================
   8. PANEL — COMPONENTE BASE
   ============================================================ */
.dashboard-panel {
  background-color: var(--color-bg-panel);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: background-color var(--transition-fast);
  position: relative;
}

.dashboard-panel:hover {
  background-color: var(--color-bg-panel-hover);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.panel-title {
  font-size: var(--font-size-sm);
  font-weight: 700;
  color: var(--color-cyan);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-shadow: var(--glow-cyan);
}

.panel-badge {
  font-size: var(--font-size-xs);
  padding: 2px var(--space-sm);
  border-radius: 3px;
  background-color: rgba(0, 212, 255, 0.12);
  border: 1px solid var(--color-border-active);
  color: var(--color-cyan);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.panel-body {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: var(--space-sm);
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
}

.panel-body::-webkit-scrollbar {
  width: 4px;
}

.panel-body::-webkit-scrollbar-track {
  background: transparent;
}

.panel-body::-webkit-scrollbar-thumb {
  background-color: var(--color-border);
  border-radius: 2px;
}

/* Paneles con IDs específicos — posición en el grid */
#panel-pipelines {
  grid-column: 1;
  grid-row: 1;
}

#panel-incidents {
  grid-column: 2;
  grid-row: 1;
}

#panel-jira {
  grid-column: 3;
  grid-row: 1 / 3;
}

#panel-metrics {
  grid-column: 1;
  grid-row: 2;
}

#panel-activity {
  grid-column: 2;
  grid-row: 2;
}

/* ============================================================
   9. PIPELINES LIST
   ============================================================ */
#pipelines-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

#badge-pipelines {
  background-color: rgba(0, 255, 136, 0.1);
  border-color: var(--color-green);
  color: var(--color-green);
}

/* ============================================================
   10. JIRA BOARD — COLUMNAS KANBAN
   ============================================================ */
#panel-jira .panel-body {
  display: flex;
  gap: var(--space-sm);
  padding: var(--space-sm);
}

.jira-column {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  min-width: 0;
}

.jira-col-title {
  font-size: var(--font-size-xs);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-cyan);
  opacity: 0.7;
  padding-bottom: var(--space-xs);
  border-bottom: 1px solid var(--color-border);
  text-align: center;
  flex-shrink: 0;
}

.jira-col-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
}

.jira-col-body::-webkit-scrollbar {
  width: 3px;
}

.jira-col-body::-webkit-scrollbar-thumb {
  background-color: var(--color-border);
  border-radius: 2px;
}

/* ============================================================
   11. MODAL
   ============================================================ */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background-color: rgba(5, 10, 15, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--transition-normal);
}

.modal-overlay.is-active {
  opacity: 1;
  pointer-events: all;
}

.modal-box {
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-active);
  border-radius: var(--panel-radius);
  box-shadow: var(--glow-cyan);
  width: min(560px, 90vw);
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: translateY(12px);
  transition: transform var(--transition-normal);
}

.modal-overlay.is-active .modal-box {
  transform: translateY(0);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.modal-title {
  font-size: var(--font-size-base);
  font-weight: 700;
  color: var(--color-cyan);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  text-shadow: var(--glow-cyan);
}

.modal-close-btn {
  background: none;
  border: 1px solid var(--color-border);
  color: var(--color-cyan);
  font-family: var(--font-mono);
  font-size: var(--font-size-base);
  width: 28px;
  height: 28px;
  border-radius: 3px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
  line-height: 1;
}

.modal-close-btn:hover {
  border-color: var(--color-border-active);
  box-shadow: var(--glow-cyan);
}

.modal-content {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-lg);
  font-size: var(--font-size-sm);
  color: var(--color-cyan);
  opacity: 0.85;
  line-height: 1.6;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border) transparent;
}

.modal-content::-webkit-scrollbar {
  width: 4px;
}

.modal-content::-webkit-scrollbar-thumb {
  background-color: var(--color-border);
  border-radius: 2px;
}

/* ============================================================
   12. ANIMACIONES
   ============================================================ */
@keyframes pulse-dot {
  0%, 100% { opacity: 1;   transform: scale(1); }
  50%       { opacity: 0.5; transform: scale(0.85); }
}

@keyframes scanline {
  0%   { transform: translateY(-100%); }
  100% { transform: translateY(100vh); }
}

@keyframes flicker {
  0%, 95%, 100% { opacity: 1; }
  96%           { opacity: 0.85; }
  97%           { opacity: 1; }
  98%           { opacity: 0.9; }
}

/* Scanline decorativa sobre el app-root */
#app-root::after {
  content: '';
  position: fixed;
  inset: 0;
  z-index: 200;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 3px,
    rgba(0, 212, 255, 0.015) 3px,
    rgba(0, 212, 255, 0.015) 4px
  );
  pointer-events: none;
  animation: flicker 8s ease-in-out infinite;
}
